package store

import (
	"database/sql"
	"time"
)

// promoteExpired performs the deterministic transfer after a lease ran out.
//
// When a waiter exists, the first queued request becomes the new holder using the
// lease seconds it requested when it entered the queue, and is removed from the
// queue. With no waiter the resource returns to holderless state. The former owner
// is remembered so its late release/reentry keeps returning LEASE_EXPIRED even
// after a new holder took over.
func promoteExpired(tx *sql.Tx, resourceID string, row resourceRow, now time.Time) error {
	if !row.hasOwner() {
		return nil
	}

	var nextOwner string
	var nextLeaseSeconds int64
	var nextID int64
	err := tx.QueryRow(
		`SELECT id, owner_id, lease_seconds FROM waiting_requests
		 WHERE resource_id = ? ORDER BY id LIMIT 1`, resourceID,
	).Scan(&nextID, &nextOwner, &nextLeaseSeconds)
	if err == sql.ErrNoRows {
		_, err = tx.Exec(
			`UPDATE resources
			 SET owner_id = NULL, lease_expires_at = NULL, reentry_count = 0,
			     expired_owner_id = ?
			 WHERE resource_id = ?`,
			row.ownerID.String, resourceID,
		)
		return err
	}
	if err != nil {
		return err
	}

	if _, err := tx.Exec(
		`UPDATE resources
		 SET owner_id = ?, lease_expires_at = ?, reentry_count = 1,
		     expired_owner_id = ?
		 WHERE resource_id = ?`,
		nextOwner, now.Add(time.Duration(nextLeaseSeconds)*time.Second).UnixMilli(),
		row.ownerID.String, resourceID,
	); err != nil {
		return err
	}
	_, err = tx.Exec(`DELETE FROM waiting_requests WHERE id = ?`, nextID)
	return err
}

// promoteVoluntary transfers the lock because the current holder released it while
// its lease was still valid. No former-owner marker is recorded.
func promoteVoluntary(tx *sql.Tx, resourceID string, now time.Time) error {
	var nextOwner string
	var nextLeaseSeconds int64
	var nextID int64
	err := tx.QueryRow(
		`SELECT id, owner_id, lease_seconds FROM waiting_requests
		 WHERE resource_id = ? ORDER BY id LIMIT 1`, resourceID,
	).Scan(&nextID, &nextOwner, &nextLeaseSeconds)
	if err == sql.ErrNoRows {
		_, err = tx.Exec(
			`UPDATE resources
			 SET owner_id = NULL, lease_expires_at = NULL, reentry_count = 0
			 WHERE resource_id = ?`,
			resourceID,
		)
		return err
	}
	if err != nil {
		return err
	}

	if _, err := tx.Exec(
		`UPDATE resources
		 SET owner_id = ?, lease_expires_at = ?, reentry_count = 1
		 WHERE resource_id = ?`,
		nextOwner, now.Add(time.Duration(nextLeaseSeconds)*time.Second).UnixMilli(),
		resourceID,
	); err != nil {
		return err
	}
	_, err = tx.Exec(`DELETE FROM waiting_requests WHERE id = ?`, nextID)
	return err
}
package store

import (
	"database/sql"
	"errors"
)

// CancelWaiting withdraws one pending waiting request. The current holder, the
// lease, and the reentry count are left untouched, and the remaining waiters
// keep their entry order and requested lease seconds. A caller that is not a
// pending waiter — including the current holder or an owner already promoted by
// a lease transfer — is rejected with ErrNotWaiting and nothing changes.
func (s *Store) CancelWaiting(resourceID, ownerID string) (Outcome, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return Outcome{}, err
	}
	defer tx.Rollback()

	if _, err := readRow(tx, resourceID); errors.Is(err, sql.ErrNoRows) {
		return Outcome{}, ErrResourceNotFound
	} else if err != nil {
		return Outcome{}, err
	}

	waiting, err := isWaiting(tx, resourceID, ownerID)
	if err != nil {
		return Outcome{}, err
	}
	if !waiting {
		return Outcome{}, ErrNotWaiting
	}

	if _, err := tx.Exec(
		`DELETE FROM waiting_requests WHERE resource_id = ? AND owner_id = ?`,
		resourceID, ownerID,
	); err != nil {
		return Outcome{}, err
	}
	if err := tx.Commit(); err != nil {
		return Outcome{}, err
	}
	state, err := s.getStateLocked(resourceID)
	if err != nil {
		return Outcome{}, err
	}
	return Outcome{Status: StatusCanceled, State: state}, nil
}

