// Package api exposes the distributed lock service over HTTP.
package api

import (
	"errors"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/distributed-lock-service/internal/store"
)

// NewRouter wires the public HTTP surface. Every entry keeps the error shape in
// README.md: one top-level "error" object with string "code" and "message".
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	locks := router.Group("/locks")
	{
		locks.POST("", acquireHandler(st))
		locks.POST("/release", releaseHandler(st))
		locks.POST("/reenter", reenterHandler(st))
		locks.POST("/cancel-waiting", cancelWaitingHandler(st))
		locks.GET("/:resourceId", stateHandler(st))
	}

	router.NoRoute(func(c *gin.Context) {
		writeError(c, http.StatusNotFound, "route_not_found", "no route matches this path")
	})
	return router
}

func writeError(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// mapStoreError turns a store sentinel error into the published code and HTTP
// status. The returned status is 0 when err is nil.
func mapStoreError(err error) (int, string, string) {
	switch {
	case errors.Is(err, store.ErrResourceNotFound):
		return http.StatusNotFound, "RESOURCE_NOT_FOUND", "resource does not exist"
	case errors.Is(err, store.ErrNotOwner):
		return http.StatusForbidden, "NOT_OWNER", "caller is not the current holder"
	case errors.Is(err, store.ErrLeaseExpired):
		return http.StatusConflict, "LEASE_EXPIRED", "lease has expired"
	case errors.Is(err, store.ErrDuplicateWaiting):
		return http.StatusConflict, "DUPLICATE_WAITING", "owner already has a pending waiting request"
	case errors.Is(err, store.ErrNotWaiting):
		return http.StatusConflict, "NOT_WAITING", "caller has no pending waiting request"
	default:
		return http.StatusInternalServerError, "internal_error", "request failed"
	}
}
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/distributed-lock-service/internal/store"
)

// acquireRequest is the body of POST /locks.
type acquireRequest struct {
	ResourceID   string `json:"resourceId"`
	OwnerID      string `json:"ownerId"`
	LeaseSeconds int64  `json:"leaseSeconds"`
}

// ownerRequest identifies the resource and caller for release and reenter.
type ownerRequest struct {
	ResourceID string `json:"resourceId"`
	OwnerID    string `json:"ownerId"`
}

// stateView is the fixed, public shape of a resource state response.
type stateView struct {
	ResourceID     string             `json:"resourceId"`
	OwnerID        *string            `json:"ownerId"`
	LeaseExpiresAt *string            `json:"leaseExpiresAt"`
	ReentryCount   int64              `json:"reentryCount"`
	WaitingOwners  []waitingOwnerView `json:"waitingOwners"`
}

type waitingOwnerView struct {
	OwnerID              string `json:"ownerId"`
	RequestedLeaseSecond int64  `json:"requestedLeaseSeconds"`
}

// stateResponse renders the outcome and the read view together.
type stateResponse struct {
	Status string    `json:"status"`
	State  stateView `json:"state"`
}

const leaseTimeLayout = "2006-01-02T15:04:05.000Z07:00"

func renderState(state store.State) stateView {
	view := stateView{
		ResourceID:    state.ResourceID,
		ReentryCount:  state.ReentryCount,
		WaitingOwners: []waitingOwnerView{},
	}
	if state.OwnerID != "" {
		owner := state.OwnerID
		view.OwnerID = &owner
	}
	if !state.LeaseExpiresAt.IsZero() {
		expires := state.LeaseExpiresAt.Format(leaseTimeLayout)
		view.LeaseExpiresAt = &expires
	}
	for _, waiting := range state.WaitingOwners {
		view.WaitingOwners = append(view.WaitingOwners, waitingOwnerView{
			OwnerID:              waiting.OwnerID,
			RequestedLeaseSecond: waiting.RequestedLeaseSecond,
		})
	}
	return view
}

func acquireHandler(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		var req acquireRequest
		if err := c.ShouldBindJSON(&req); err != nil {
			writeError(c, http.StatusBadRequest, "INVALID_REQUEST", "request body must be valid JSON")
			return
		}
		if req.ResourceID == "" {
			writeError(c, http.StatusBadRequest, "MISSING_RESOURCE_ID", "resourceId is required")
			return
		}
		if req.OwnerID == "" {
			writeError(c, http.StatusBadRequest, "MISSING_OWNER_ID", "ownerId is required")
			return
		}
		if req.LeaseSeconds <= 0 {
			writeError(c, http.StatusBadRequest, "INVALID_LEASE_SECONDS", "leaseSeconds must be greater than zero")
			return
		}

		outcome, err := st.Acquire(req.ResourceID, req.OwnerID, req.LeaseSeconds)
		if err != nil {
			status, code, message := mapStoreError(err)
			writeError(c, status, code, message)
			return
		}
		c.JSON(http.StatusOK, stateResponse{Status: outcome.Status, State: renderState(outcome.State)})
	}
}

